query GetRepository($owner: String!, $name: String!, $first: Int = 5) {
  repository(owner: $owner, name: $name) {
    id
    name
    stargazerCount
    issues(first: $first, states: OPEN) {
      nodes { number title author { login } }
    }
    ...RepoMeta
  }
}

fragment RepoMeta on Repository {
  description
  url
}
